-- Preserve baseline linked effects and proc metadata for replacement IDs.
DROP TEMPORARY TABLE IF EXISTS `rogue_path_install_map`;
CREATE TEMPORARY TABLE `rogue_path_install_map` (`base_id` INT UNSIGNED PRIMARY KEY, `celestial_id` INT UNSIGNED NOT NULL, `sha_id` INT UNSIGNED NOT NULL);
DROP TEMPORARY TABLE IF EXISTS `rogue_path_effect_map`;
CREATE TEMPORARY TABLE `rogue_path_effect_map` AS SELECT * FROM `rogue_path_install_map`;
DELETE FROM `spell_linked_spell` WHERE ABS(`spell_trigger`) BETWEEN 86000 AND 86999;
DELETE FROM `spell_proc` WHERE ABS(`SpellId`) BETWEEN 86000 AND 86999;
SELECT SIGN(l.`spell_trigger`)*CAST(m.`celestial_id` AS SIGNED), IF(e.`base_id` IS NULL, l.`spell_effect`, SIGN(l.`spell_effect`)*CAST(e.`celestial_id` AS SIGNED)), l.`type`, CONCAT('Cultivation / Rogue: ', l.`comment`)
FROM `spell_linked_spell` l JOIN `rogue_path_install_map` m ON ABS(l.`spell_trigger`)=m.`base_id` LEFT JOIN `rogue_path_effect_map` e ON ABS(l.`spell_effect`)=e.`base_id`;
SELECT SIGN(p.`SpellId`)*CAST(m.`celestial_id` AS SIGNED), p.`SchoolMask`, p.`SpellFamilyName`, p.`SpellFamilyMask0`, p.`SpellFamilyMask1`, p.`SpellFamilyMask2`, p.`ProcFlags`, p.`SpellTypeMask`, p.`SpellPhaseMask`, p.`HitMask`, p.`AttributesMask`, p.`DisableEffectsMask`, p.`ProcsPerMinute`, p.`Chance`, p.`Cooldown`, p.`Charges`
FROM `spell_proc` p JOIN `rogue_path_install_map` m ON ABS(p.`SpellId`)=m.`base_id` WHERE m.`base_id` IN (35541,35550,35551,35552,35553);
SELECT SIGN(l.`spell_trigger`)*CAST(m.`sha_id` AS SIGNED), IF(e.`base_id` IS NULL, l.`spell_effect`, SIGN(l.`spell_effect`)*CAST(e.`sha_id` AS SIGNED)), l.`type`, CONCAT('Cultivation / Rogue: ', l.`comment`)
FROM `spell_linked_spell` l JOIN `rogue_path_install_map` m ON ABS(l.`spell_trigger`)=m.`base_id` LEFT JOIN `rogue_path_effect_map` e ON ABS(l.`spell_effect`)=e.`base_id`;
SELECT SIGN(p.`SpellId`)*CAST(m.`sha_id` AS SIGNED), p.`SchoolMask`, p.`SpellFamilyName`, p.`SpellFamilyMask0`, p.`SpellFamilyMask1`, p.`SpellFamilyMask2`, p.`ProcFlags`, p.`SpellTypeMask`, p.`SpellPhaseMask`, p.`HitMask`, p.`AttributesMask`, p.`DisableEffectsMask`, p.`ProcsPerMinute`, p.`Chance`, p.`Cooldown`, p.`Charges`
FROM `spell_proc` p JOIN `rogue_path_install_map` m ON ABS(p.`SpellId`)=m.`base_id` WHERE m.`base_id` IN (35541,35550,35551,35552,35553);
DROP TEMPORARY TABLE `rogue_path_install_map`;
DROP TEMPORARY TABLE `rogue_path_effect_map`;
